#!/usr/bin/env python3
"""validate_proof.py -- syntactic validator for proof.txt against obligations.txt.

Structural checker (NOT a logical verifier). Checks:

  C1  structure        every proof section (L1-L3, O1-O9, MAIN THEOREM)
                       ends with a tombstone (U+220E) line
  C2  justifications   every numbered deduction step carries at least one
                       bracketed [...] justification, on its own line or
                       on its immediate continuation lines
  C3  bracket balance  '[' and ']' are balanced on every line
  C4  coverage         every Label declared in obligations.txt has a
                       matching proof section in proof.txt and is marked
                       "discharged" in the STATUS SUMMARY
  C5  references       rule names (S-*) and numbered citations (O#, L#,
                       A#, P#) resolve to known targets

Usage:  python3 validate_proof.py [proof.txt] [obligations.txt]
Exit:   0 = all checks passed, 1 = findings reported, 2 = missing input.

Limitation: this script is untrusted and purely syntactic. A clean pass
means the document is structurally complete and internally consistent,
not that its mathematics is true. Logical validation requires a trusted
kernel (see validation.txt, Route A).
"""

import re
import sys
from pathlib import Path

RULES = {
    "S-PlusLeft", "S-PlusRight", "S-MinusLeft", "S-MinusRight", "S-Abs",
    "S-AbsZero", "S-AbsPos", "S-AbsNeg", "S-Plus", "S-Minus",
    "S-Refl", "S-Trans",
}

HDR_O = re.compile(r"^(O\d+)\.\s*(.*)$")
HDR_L = re.compile(r"^(L\d+)\.\s*(.*)$")
HDR_ADM = re.compile(r"^0\.\s")
HDR_THM = re.compile(r"^MAIN THEOREM\b")
HDR_SUM = re.compile(r"^STATUS SUMMARY\b")
NUM = re.compile(r"^\s*(\d+(?:\.\d+)*)\.?\s+\S")
DASH = re.compile(r"^-{5,}\s*$")
TOMB = re.compile(r"^\s*∎")
OBLIG_HDR = re.compile(r"^O(\d+)\.\s")
LABEL = re.compile(r"^\s*Label:\s*([A-Za-z0-9-]+)\s*$")


def norm(text):
    return re.sub(r"[^a-z0-9]", "", text.lower())


def scan_sections(lines):
    """Split the document into sections at column-0 headers."""
    sections, cur = [], None
    for i, raw in enumerate(lines, 1):
        header, kind = None, "proof"
        m = HDR_O.match(raw) or HDR_L.match(raw)
        if m:
            header = {"name": m.group(1), "title": m.group(2).strip()}
        elif HDR_ADM.match(raw):
            header, kind = {"name": "SEC0", "title": raw.strip()}, "admitted"
        elif HDR_THM.match(raw):
            header = {"name": "T", "title": raw.strip()}
        elif HDR_SUM.match(raw):
            header, kind = {"name": "SUMMARY", "title": raw.strip()}, "summary"
        if header is not None:
            cur = {"name": header["name"], "title": header["title"],
                   "kind": kind, "start": i, "body": []}
            sections.append(cur)
        elif cur is not None:
            cur["body"].append((i, raw))
    return sections


def check_tombstones(sections, errors):
    for s in sections:
        if s["kind"] != "proof":
            continue
        content = [t for _, t in s["body"] if t.strip() and not DASH.match(t)]
        if not content or not TOMB.match(content[-1]):
            errors.append(
                f"C1  section {s['name']} (starts line {s['start']}): "
                f"proof does not end with a tombstone (∎)")


def check_justifications(sections, errors):
    for s in sections:
        if s["kind"] != "proof":
            continue
        body, j = s["body"], 0
        while j < len(body):
            lineno, text = body[j]
            m = NUM.match(text)
            if not m:
                j += 1
                continue
            group, k = [text], j + 1
            while k < len(body):
                nl, nt = body[k]
                if NUM.match(nt) or not nt.strip() or DASH.match(nt):
                    break
                group.append(nt)
                k += 1
            if not any("[" in g and "]" in g for g in group):
                errors.append(
                    f"C2  section {s['name']} line {lineno}: deduction "
                    f"step {m.group(1)} has no bracketed [...] justification")
            j = k


def check_brackets(lines, errors):
    for i, raw in enumerate(lines, 1):
        if raw.count("[") != raw.count("]"):
            errors.append(f"C3  line {i}: unbalanced square brackets")


def obligation_labels(oblig_path):
    labels, pending = {}, None
    text = oblig_path.read_text(encoding="utf-8")
    for raw in text.splitlines():
        m = OBLIG_HDR.match(raw)
        if m:
            pending = int(m.group(1))
            continue
        m = LABEL.match(raw)
        if m and pending is not None:
            labels[pending] = m.group(1)
            pending = None
    has_main = bool(re.search(r"^\s*Label:\s*main-theorem\s*$", text, re.M))
    return labels, has_main


def check_coverage(sections, labels, has_main, proof_name, errors):
    proofs = [s for s in sections if s["kind"] == "proof"]
    proof_o = {int(m.group(1)): s for s in proofs
               for m in [re.match(r"O(\d+)$", s["name"])] if m}
    for n in sorted(labels):
        if n not in proof_o:
            errors.append(f"C4  obligation O{n} ({labels[n]}): no proof "
                          f"section in {proof_name}")
            continue
        if norm(proof_o[n]["title"]) != norm(labels[n]):
            errors.append(
                f"C4  obligation O{n}: label mismatch (obligations.txt: "
                f"{labels[n]!r} vs proof.txt: {proof_o[n]['title']!r})")
    if not has_main:
        errors.append("C4  obligations.txt declares no 'main-theorem' label")
    elif not any(s["name"] == "T" for s in proofs):
        errors.append("C4  no MAIN THEOREM section in proof.txt")
    summary = next((s for s in sections if s["kind"] == "summary"), None)
    if summary is None:
        errors.append("C4  no STATUS SUMMARY section in proof.txt")
        return
    body = [t for _, t in summary["body"]]
    for n in sorted(labels):
        hit = next((t for t in body if re.search(rf"\bO{n}\b", t)), None)
        if hit is None or "discharged" not in hit:
            errors.append(f"C4  obligation O{n} not marked discharged "
                          f"in STATUS SUMMARY")
    tline = next((t for t in body if re.match(r"^\s*T\s", t)), None)
    if has_main and (tline is None or "discharged" not in tline):
        errors.append("C4  main theorem not marked discharged in STATUS SUMMARY")


def check_references(text, errors):
    for tok in sorted(set(re.findall(r"\bS-[A-Za-z]+\b", text))):
        if tok not in RULES:
            errors.append(f"C5  citation of unknown rule name: {tok}")
    for kind, hi in (("O", 9), ("L", 3), ("A", 5)):
        for n in sorted({int(x) for x in re.findall(rf"\b{kind}(\d+)\b", text)}):
            if not 1 <= n <= hi:
                errors.append(f"C5  citation of unknown {kind}{n} "
                              f"(known: {kind}1..{kind}{hi})")
    for n in sorted({int(x) for x in re.findall(r"\bP(\d+)\b", text)}):
        if n not in (1, 2, 3):
            errors.append(f"C5  citation of unknown P{n} "
                          f"(spec.txt defines P1-P3)")


def main(argv):
    proof_path = Path(argv[1]) if len(argv) > 1 else Path("proof.txt")
    oblig_path = Path(argv[2]) if len(argv) > 2 else Path("obligations.txt")
    if not proof_path.exists() or not oblig_path.exists():
        print("error: proof.txt / obligations.txt not found", file=sys.stderr)
        return 2

    text = proof_path.read_text(encoding="utf-8")
    lines = text.splitlines()
    sections = scan_sections(lines)

    errors = []
    check_tombstones(sections, errors)
    check_justifications(sections, errors)
    check_brackets(lines, errors)
    labels, has_main = obligation_labels(oblig_path)
    check_coverage(sections, labels, has_main, proof_path.name, errors)
    check_references(text, errors)

    proofs = [s for s in sections if s["kind"] == "proof"]
    print(f"Validating {proof_path.name} against {oblig_path.name}")
    print(f"  proof sections : {', '.join(s['name'] for s in proofs)}")
    print(f"  obligations    : {len(labels)} declared in obligations.txt"
          f" (+ main theorem: {'yes' if has_main else 'NO'})")
    print()
    if errors:
        print(f"FAILED: {len(errors)} finding(s)")
        for e in errors:
            print(f"  - {e}")
        return 1
    print("PASSED: all structural checks satisfied")
    print("  C1  every proof section ends with a tombstone (∎)")
    print("  C2  every deduction step carries a bracketed justification")
    print("  C3  square brackets balanced throughout")
    print(f"  C4  all {len(labels)} obligations and the main theorem are "
          f"proven and marked discharged")
    print("  C5  all rule/lemma/axiom citations resolve")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
